-- Remote MCP Gateway: durable ASYNC job store (R13 section 14.4, connector doc section 13). FILE ONLY: this migration has NOT been applied anywhere and must not be applied without the owner.
--
-- Shape: one table, service-role only (RLS on, no policy, every grant to anon/authenticated revoked), reached ONLY through the SECURITY DEFINER functions below.
-- Every read and every cancel takes the OWNER principal as an argument and filters on it, so a job of another principal is indistinguishable from a job that does not exist.
-- Job ids are unpredictable (generated by the caller from a random UUID, never sequential). Idempotency: the same owner + same input fingerprint returns the live job instead of a second one.
-- Worker side: claim uses FOR UPDATE SKIP LOCKED and takes a lease; a worker that dies leaves an expired lease, mcp_job_recover puts the job back (or fails it after max attempts).
-- Cancellation is immediate in the table and cooperative in the worker: complete/fail from a worker that no longer owns a running job do nothing (the worker learns through mcp_job_is_live).
-- Results are written only by a worker, expire with the job, and mcp_job_purge deletes expired rows.

CREATE TABLE IF NOT EXISTS public.mcp_jobs (
  job_id        text PRIMARY KEY CHECK (job_id ~ '^job_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'),
  owner         text NOT NULL CHECK (length(owner) BETWEEN 3 AND 80),
  host          text NOT NULL CHECK (host IN ('claude', 'chatgpt', 'gemini', 'cursor', 'grok', 'deepseek', 'meta')),
  install_id    text NOT NULL CHECK (length(install_id) BETWEEN 1 AND 120),
  tool          text NOT NULL CHECK (tool = 'create_itinerary'),
  input         jsonb NOT NULL,
  fingerprint   text NOT NULL CHECK (fingerprint ~ '^[0-9a-f]{64}$'),
  status        text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'cancelled')),
  attempts      integer NOT NULL DEFAULT 0,
  worker_id     text,
  lease_until   timestamptz,
  result        jsonb,
  error_code    text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz NOT NULL
);

CREATE INDEX IF NOT EXISTS mcp_jobs_owner_fp_idx ON public.mcp_jobs (owner, fingerprint);
CREATE INDEX IF NOT EXISTS mcp_jobs_claim_idx ON public.mcp_jobs (updated_at) WHERE status = 'queued';
CREATE INDEX IF NOT EXISTS mcp_jobs_lease_idx ON public.mcp_jobs (lease_until) WHERE status = 'running';
CREATE INDEX IF NOT EXISTS mcp_jobs_expiry_idx ON public.mcp_jobs (expires_at);

ALTER TABLE public.mcp_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.mcp_jobs FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.mcp_jobs TO service_role;

-- create (or return the live job of the same owner and input)
CREATE OR REPLACE FUNCTION public.mcp_job_create(
  p_job_id text, p_owner text, p_host text, p_install text, p_tool text, p_input jsonb, p_fingerprint text, p_ttl_seconds integer
)
RETURNS SETOF public.mcp_jobs
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE r public.mcp_jobs%ROWTYPE;
BEGIN
  IF p_ttl_seconds IS NULL OR p_ttl_seconds < 60 OR p_ttl_seconds > 86400 THEN RAISE EXCEPTION 'mcp_job_create: ttl out of range' USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_owner || '|' || p_fingerprint, 0));
  SELECT * INTO r FROM public.mcp_jobs WHERE owner = p_owner AND fingerprint = p_fingerprint AND expires_at > now() ORDER BY created_at DESC LIMIT 1;
  IF FOUND THEN RETURN NEXT r; RETURN; END IF;
  INSERT INTO public.mcp_jobs (job_id, owner, host, install_id, tool, input, fingerprint, expires_at)
  VALUES (p_job_id, p_owner, p_host, p_install, p_tool, p_input, p_fingerprint, now() + make_interval(secs => p_ttl_seconds))
  RETURNING * INTO r;
  RETURN NEXT r;
END
$fn$;

-- read: only the owner sees a job
CREATE OR REPLACE FUNCTION public.mcp_job_get(p_job_id text, p_owner text)
RETURNS SETOF public.mcp_jobs
LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
  SELECT * FROM public.mcp_jobs WHERE job_id = p_job_id AND owner = p_owner;
$fn$;

-- cancel: owner only; queued and running become cancelled at once, a finished job is returned unchanged
CREATE OR REPLACE FUNCTION public.mcp_job_cancel(p_job_id text, p_owner text)
RETURNS SETOF public.mcp_jobs
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE r public.mcp_jobs%ROWTYPE;
BEGIN
  UPDATE public.mcp_jobs SET status = 'cancelled', worker_id = NULL, lease_until = NULL, updated_at = now()
   WHERE job_id = p_job_id AND owner = p_owner AND status IN ('queued', 'running') RETURNING * INTO r;
  IF NOT FOUND THEN SELECT * INTO r FROM public.mcp_jobs WHERE job_id = p_job_id AND owner = p_owner; END IF;
  IF r.job_id IS NOT NULL THEN RETURN NEXT r; END IF;
END
$fn$;

-- worker: take the longest-waiting live queued job under a lease (a requeued job waits behind the others: ordered by updated_at)
CREATE OR REPLACE FUNCTION public.mcp_job_claim(p_worker text, p_lease_seconds integer)
RETURNS SETOF public.mcp_jobs
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE r public.mcp_jobs%ROWTYPE;
BEGIN
  IF p_lease_seconds IS NULL OR p_lease_seconds < 5 OR p_lease_seconds > 900 THEN RAISE EXCEPTION 'mcp_job_claim: lease out of range' USING ERRCODE = '22023'; END IF;
  SELECT * INTO r FROM public.mcp_jobs WHERE status = 'queued' AND expires_at > now() ORDER BY updated_at, created_at FOR UPDATE SKIP LOCKED LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;
  UPDATE public.mcp_jobs SET status = 'running', worker_id = p_worker, lease_until = now() + make_interval(secs => p_lease_seconds), attempts = attempts + 1, updated_at = now()
   WHERE job_id = r.job_id RETURNING * INTO r;
  RETURN NEXT r;
END
$fn$;

-- worker: is this job still running and mine? (false after a cancel, an expiry, or a lease taken over)
CREATE OR REPLACE FUNCTION public.mcp_job_is_live(p_job_id text, p_worker text)
RETURNS boolean
LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
  SELECT EXISTS (SELECT 1 FROM public.mcp_jobs WHERE job_id = p_job_id AND worker_id = p_worker AND status = 'running' AND expires_at > now());
$fn$;

-- worker: finish. Only the worker that still owns the running job can write the result; true = written
CREATE OR REPLACE FUNCTION public.mcp_job_complete(p_job_id text, p_worker text, p_result jsonb)
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
BEGIN
  UPDATE public.mcp_jobs SET status = 'succeeded', result = p_result, worker_id = NULL, lease_until = NULL, updated_at = now()
   WHERE job_id = p_job_id AND worker_id = p_worker AND status = 'running';
  RETURN FOUND;
END
$fn$;

-- worker: fail. retryable and attempts left = back to the queue; otherwise terminal
CREATE OR REPLACE FUNCTION public.mcp_job_fail(p_job_id text, p_worker text, p_code text, p_retryable boolean, p_max_attempts integer)
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
BEGIN
  UPDATE public.mcp_jobs
     SET status = CASE WHEN p_retryable AND attempts < p_max_attempts THEN 'queued' ELSE 'failed' END,
         error_code = left(p_code, 60), worker_id = NULL, lease_until = NULL, updated_at = now()
   WHERE job_id = p_job_id AND worker_id = p_worker AND status = 'running';
  RETURN FOUND;
END
$fn$;

-- recovery: running jobs whose lease ran out (a dead worker) go back to the queue, or fail after max attempts. Returns the number touched
CREATE OR REPLACE FUNCTION public.mcp_job_recover(p_max_attempts integer)
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE n integer;
BEGIN
  UPDATE public.mcp_jobs
     SET status = CASE WHEN attempts < p_max_attempts THEN 'queued' ELSE 'failed' END,
         error_code = CASE WHEN attempts < p_max_attempts THEN error_code ELSE 'worker_lost' END,
         worker_id = NULL, lease_until = NULL, updated_at = now()
   WHERE status = 'running' AND lease_until < now();
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END
$fn$;

-- retention: expired jobs and their results are deleted. Returns the number deleted
CREATE OR REPLACE FUNCTION public.mcp_job_purge()
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE n integer;
BEGIN
  DELETE FROM public.mcp_jobs WHERE expires_at < now() - interval '1 hour';
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END
$fn$;

REVOKE EXECUTE ON FUNCTION public.mcp_job_create(text,text,text,text,text,jsonb,text,integer) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.mcp_job_create(text,text,text,text,text,jsonb,text,integer) TO service_role;
REVOKE EXECUTE ON FUNCTION public.mcp_job_get(text,text) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.mcp_job_get(text,text) TO service_role;
REVOKE EXECUTE ON FUNCTION public.mcp_job_cancel(text,text) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.mcp_job_cancel(text,text) TO service_role;
REVOKE EXECUTE ON FUNCTION public.mcp_job_claim(text,integer) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.mcp_job_claim(text,integer) TO service_role;
REVOKE EXECUTE ON FUNCTION public.mcp_job_is_live(text,text) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.mcp_job_is_live(text,text) TO service_role;
REVOKE EXECUTE ON FUNCTION public.mcp_job_complete(text,text,jsonb) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.mcp_job_complete(text,text,jsonb) TO service_role;
REVOKE EXECUTE ON FUNCTION public.mcp_job_fail(text,text,text,boolean,integer) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.mcp_job_fail(text,text,text,boolean,integer) TO service_role;
REVOKE EXECUTE ON FUNCTION public.mcp_job_recover(integer) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.mcp_job_recover(integer) TO service_role;
REVOKE EXECUTE ON FUNCTION public.mcp_job_purge() FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.mcp_job_purge() TO service_role;
